        "current": "CREATE UNIQUE INDEX IF NOT EXISTS multi_hop_courier_live_item ON multi_hop_couriers(item_id) WHERE status IN ('offered','ready','first_leg','second_leg');\nCREATE TABLE IF NOT EXISTS multi_hop_courier_requests (\n account_id TEXT NOT NULL REFERENCES accounts(id),request_key TEXT NOT NULL CHECK(char_length(request_key) BETWEEN 1 AND 128),body_hash TEXT NOT NULL CHECK(char_length(body_hash)=64),original_character TEXT NOT NULL REFERENCES characters(id),network_id TEXT NOT NULL REFERENCES multi_hop_couriers(id),receipt JSONB NOT NULL,PRIMARY KEY(account_id,request_key));\n\nCREATE TABLE IF NOT EXISTS cross_dock_links (\n id TEXT PRIMARY KEY,\n network_id TEXT NOT NULL REFERENCES multi_hop_couriers(id),\n network_source_hash TEXT NOT NULL CHECK(char_length(network_source_hash)=64),\n hub_id TEXT NOT NULL REFERENCES company_logistics_hubs(id),\n hub_source JSONB NOT NULL,\n item_id TEXT NOT NULL REFERENCES item_instances(id),\n owner_account TEXT NOT NULL REFERENCES accounts(id),\n owner_character TEXT NOT NULL REFERENCES characters(id),\n first_account TEXT NOT NULL REFERENCES accounts(id),\n first_character TEXT NOT NULL REFERENCES characters(id),\n second_account TEXT NOT NULL REFERENCES accounts(id),\n second_character TEXT NOT NULL REFERENCES characters(id),\n source_hash TEXT NOT NULL CHECK(char_length(source_hash)=64),\n expires_at TIMESTAMPTZ NOT NULL,\n first_consent BOOLEAN NOT NULL DEFAULT false,\n second_consent BOOLEAN NOT NULL DEFAULT false,\n status TEXT NOT NULL CHECK(status IN ('offered','active','completed','released','expired','void')),\n completion JSONB,\n CHECK(owner_account<>first_account AND owner_account<>second_account AND first_account<>second_account),\n CHECK(owner_character<>first_character AND owner_character<>second_character AND first_character<>second_character),\n CHECK(status<>'active' OR (first_consent AND second_consent)),\n CHECK((status='completed')=(completion IS NOT NULL))\n);\nCREATE INDEX IF NOT EXISTS cross_dock_hub_status ON cross_dock_links(hub_id,status,expires_at);\nCREATE INDEX IF NOT EXISTS cross_dock_network_status ON cross_dock_links(network_id,status,expires_at);\nCREATE TABLE IF NOT EXISTS cross_dock_requests (\n account_id TEXT NOT NULL REFERENCES accounts(id),\n request_key TEXT NOT NULL,\n body_hash TEXT NOT NULL CHECK(char_length(body_hash)=64),\n original_character TEXT NOT NULL REFERENCES characters(id),\n link_id TEXT NOT NULL REFERENCES cross_dock_links(id),\n receipt JSONB NOT NULL,\n PRIMARY KEY(account_id,request_key)\n);\n\nCREATE TABLE IF NOT EXISTS production_slot_reservations (\n id TEXT PRIMARY KEY,commission_id TEXT NOT NULL REFERENCES commissioned_crafting_contracts(id),commission_source_hash TEXT NOT NULL CHECK(char_length(commission_source_hash)=64),business_id TEXT NOT NULL REFERENCES business_depots(id),\n maker_account TEXT NOT NULL REFERENCES accounts(id),maker_character TEXT NOT NULL REFERENCES characters(id),customer_account TEXT NOT NULL REFERENCES accounts(id),customer_character TEXT NOT NULL REFERENCES characters(id),\n profile_revision INT NOT NULL CHECK(profile_revision>=1),profile_source JSONB NOT NULL,observed_at TIMESTAMPTZ NOT NULL,ready_at TIMESTAMPTZ NOT NULL,deadline TIMESTAMPTZ NOT NULL,\n source_hash TEXT NOT NULL CHECK(char_length(source_hash)=64),status TEXT NOT NULL CHECK(status IN ('offered','active','consumed','released','expired','void')),completion JSONB,\n CHECK(maker_account<>customer_account AND maker_character<>customer_character),CHECK(ready_at<deadline),CHECK((status='consumed')=(completion IS NOT NULL)));\nCREATE UNIQUE INDEX IF NOT EXISTS production_slot_one_business ON production_slot_reservations(business_id) WHERE status='active';\nCREATE UNIQUE INDEX IF NOT EXISTS production_slot_live_commission ON production_slot_reservations(commission_id) WHERE status IN ('offered','active');\nCREATE TABLE IF NOT EXISTS production_slot_requests (\n account_id TEXT NOT NULL REFERENCES accounts(id),request_key TEXT NOT NULL CHECK(char_length(request_key) BETWEEN 1 AND 128),body_hash TEXT NOT NULL CHECK(char_length(body_hash)=64),original_character TEXT NOT NULL REFERENCES characters(id),reservation_id TEXT NOT NULL REFERENCES production_slot_reservations(id),receipt JSONB NOT NULL,PRIMARY KEY(account_id,request_key));\n\n-- N10 proposal only. Coordinator installs after genuine prelocker/private estate integration.\nCREATE TABLE IF NOT EXISTS merchant_return_rights (\n id TEXT PRIMARY KEY, sale_id TEXT NOT NULL REFERENCES consignments(id), sale_hash TEXT NOT NULL,\n item_id TEXT NOT NULL REFERENCES item_instances(id), seller_account TEXT NOT NULL REFERENCES accounts(id),\n seller_character TEXT NOT NULL REFERENCES characters(id), buyer_account TEXT NOT NULL REFERENCES accounts(id),\n buyer_character TEXT NOT NULL REFERENCES characters(id), refund_cash BIGINT NOT NULL CHECK(refund_cash BETWEEN 1 AND 1000000),\n escrow_cash BIGINT NOT NULL CHECK(escrow_cash>=0), paid_cash BIGINT NOT NULL DEFAULT 0 CHECK(paid_cash>=0),\n refunded_cash BIGINT NOT NULL DEFAULT 0 CHECK(refunded_cash>=0), condition_floor INTEGER NOT NULL CHECK(condition_floor BETWEEN 10 AND 150),\n expires_at TIMESTAMPTZ NOT NULL, source_hash TEXT NOT NULL, reserve_journal TEXT NOT NULL UNIQUE REFERENCES transactions(id),\n state TEXT NOT NULL CHECK(state IN ('offered','accepted','returned','waived','cancelled','expired','party_dead')),\n accepted_at TIMESTAMPTZ, settlement JSONB,\n CHECK(seller_account<>buyer_account), CHECK(seller_character<>buyer_character),\n CHECK(refund_cash=escrow_cash+paid_cash+refunded_cash),\n CHECK((state IN ('offered','accepted') AND escrow_cash=refund_cash AND settlement IS NULL) OR (state NOT IN ('offered','accepted') AND escrow_cash=0 AND settlement IS NOT NULL)),\n CHECK((state='returned' AND paid_cash=refund_cash AND refunded_cash=0) OR (state<>'returned' AND paid_cash=0)),\n CHECK(state NOT IN ('accepted','returned','waived') OR accepted_at IS NOT NULL)\n);\nCREATE UNIQUE INDEX IF NOT EXISTS merchant_return_one_live_sale ON merchant_return_rights(sale_id) WHERE state IN ('offered','accepted');\nCREATE TABLE IF NOT EXISTS merchant_return_requests (\n account_id TEXT NOT NULL, key_hash TEXT NOT NULL, body_hash TEXT NOT NULL, run_id TEXT NOT NULL UNIQUE,\n request_json JSONB NOT NULL, receipt JSONB, account_ref TEXT REFERENCES accounts(id),\n original_character TEXT REFERENCES characters(id), return_ref TEXT REFERENCES merchant_return_rights(id),\n PRIMARY KEY(account_id,key_hash), CHECK(account_ref IS NULL OR account_ref=account_id),\n CHECK((receipt IS NULL AND account_ref IS NULL AND original_character IS NULL AND return_ref IS NULL) OR\n (receipt IS NOT NULL AND account_ref IS NOT NULL AND original_character IS NOT NULL AND return_ref IS NOT NULL))\n);\n",
