export const DEED_MARKET_PRESERVED_FAMILIES = Object.freeze([
 Object.freeze({file:'tools/deed-quest-source-transfer.js',revision:'3aaeaa97a102babf7f56dece03860964814fe313',blob:'3eea8c22f1cd3e8da65ce707c50db091d7ceca45',sha256:'05bc98b2f26de7172675b0fb17d865ffa75d299a113807f4a5160beeb8fcfe9e'}),
 Object.freeze({file:'tools/market-operations-source-compatibility.js',revision:'7903d5032c0232fc4c368014dd4129785a1b0786',blob:'aeb1a0404c26a5999d416668ee4850e6d382a4fa',sha256:'fcfd35c512c1358ce44f793da7fc38f75389d342a305a7d9cddc0226706b18e9'})
]);
const freeze=value=>{if(value&&typeof value==='object'&&!Object.isFrozen(value)){for(const child of Object.values(value))freeze(child);Object.freeze(value);}return value;};
freeze(DEED_OVER_MARKET_SOURCE_DOMAINS);freeze(MARKET_OVER_DEED_SOURCE_DOMAINS);
const lf=text=>text.replaceAll('\r\n','\n');
const uniform=text=>typeof text==='string'&&!lf(text).includes('\r')&&(text===lf(text)||text===lf(text).replaceAll('\n','\r\n'));
const hash=text=>crypto.createHash('sha256').update(text).digest('hex');
const blob=text=>crypto.createHash('sha1').update('blob '+Buffer.byteLength(text)+'\0').update(text).digest('hex');
function recognizes(domains,file,input){
 if(!Object.hasOwn(domains,file)||!uniform(input))return false;
 const text=lf(input),pin=domains[file];return hash(text)===pin.currentSha256&&blob(text)===pin.currentBlob;
}
function transfer(domains,predecessor,file,input){
 assert.match(DEED_MARKET_SOURCE_REVISION,/^[a-f0-9]{40}$/,'UNBOUND junction has no source admission');
 assert(Object.hasOwn(domains,file),'Unknown closed source-junction domain');
 assert(uniform(input),'Only whole LF or uniform CRLF source is admitted');
 const pin=domains[file],text=lf(input);assert.equal(hash(text),pin.currentSha256,'Complete current source SHA differs');assert.equal(blob(text),pin.currentBlob,'Complete current Git blob differs');
 let baselineText=text;
 for(const inverse of pin.inverses){assert(inverse.current.length>0);assert.equal(baselineText.split(inverse.current).length,2,'Exact current inverse must occur once');baselineText=baselineText.replace(inverse.current,()=>inverse.baseline);}
 assert.equal(hash(baselineText),pin.baselineSha256,'Complete predecessor source SHA differs');assert.equal(blob(baselineText),pin.baselineBlob,'Complete predecessor Git blob differs');
 return {baselineText,sourceRevision:DEED_MARKET_SOURCE_REVISION,predecessorRevision:predecessor,phase:DEED_MARKET_SOURCE_PHASE};
}
export function assertDeedOverMarketSourceTransfer(file,input){return transfer(DEED_OVER_MARKET_SOURCE_DOMAINS,DEED_OVER_MARKET_SOURCE_PREDECESSOR,file,input);}
export function isDeedOverMarketSource(file,input){return recognizes(DEED_OVER_MARKET_SOURCE_DOMAINS,file,input);}
export function deedOverMarketSourceBaseline(file,input){return isDeedOverMarketSource(file,input)?assertDeedOverMarketSourceTransfer(file,input).baselineText:input;}
export function assertMarketOverDeedSourceTransfer(file,input){return transfer(MARKET_OVER_DEED_SOURCE_DOMAINS,MARKET_OVER_DEED_SOURCE_PREDECESSOR,file,input);}
export function isMarketOverDeedSource(file,input){return recognizes(MARKET_OVER_DEED_SOURCE_DOMAINS,file,input);}
